adcs_vec3_t unit;
double norm;
adcs_status_t st;

if ((previous == NULL) || (target == NULL) || (next == NULL) || (limited == NULL)) {
    return ADCS_E_NULL;
}

*next = (adcs_vec3_t){0, 0, 0};
*limited = 0;

if ((!adcs_is_finite_vec3(previous)) || (!adcs_is_finite_vec3(target)) ||
    (!isfinite(max_delta_nm)) || (max_delta_nm < 0.0)) {
    return ADCS_E_RANGE;
}

delta = adcs_vec3_sub(target, previous);
norm = adcs_vec3_norm(&delta);

if (norm <= max_delta_nm) {
    *next = *target;
    *limited = 0;
    return ADCS_OK;
}

st = adcs_vec3_normalize(&delta, ADCS_EPS_NORM, &unit);
if (st != ADCS_OK) {
    *next = (adcs_vec3_t){0, 0, 0};
    *limited = 0;
    return ADCS_E_RANGE;
}
*next = adcs_vec3_add(previous, &(adcs_vec3_t){max_delta_nm * unit.x,
                                               max_delta_nm * unit.y,
                                               max_delta_nm * unit.z});
*limited = 1;
return ADCS_OK;

